def countUpsideDown(low, high):
    pairs = [("0", "0"), ("1", "1"), ("8", "8"), ("6", "9"), ("9", "6")]

    def build(length, outer):
        if length == 0:
            return [""]
        if length == 1:
            return ["0", "1", "8"]
        inner = build(length - 2, False)
        res = []
        for a, b in pairs:
            if outer and a == "0":
                continue
            for mid in inner:
                res.append(a + mid + b)
        return res

    count = 0
    for length in range(len(str(low)), len(str(high)) + 1):
        for s in build(length, True):
            if low <= int(s) <= high:
                count += 1
    return count
